(3008, '올레바다', '제주특별자치도 서귀포시 이어도로 903-1', 33.2371600, 126.5111900, 'COMMERCIAL', 3, '귤, 한라봉, 천혜향 등 직접 재배한 제주 특산 과일을 판매', '귤, 한라봉, 천혜향 등 직접 재배한 제주 특산 과일을 판매', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/b05f513a-0b74-4c7e-b6e7-82023eb876e8.webp'),
(3009, '올레바당체험마을', '제주특별자치도 제주시 한림읍 한림해안로 267-6', 33.4254747, 126.2642096, 'EXPERIENCE', 2, '어린이도 쉽게 즐기는 바다낚시 체험장', '어린이도 쉽게 즐기는 바다낚시 체험장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/19/3346a943-f2df-4b2b-b425-a52aeeb6992c.webp'),
(3010, '올레올레 서귀포올레시장점', '제주특별자치도 서귀포시 중앙로54번길 35 (서귀동)', 33.2499022, 126.5632430, 'COMMERCIAL', 3, '올레올레는 제주의 정취와 환대 문화를 상품에 담아낸 제주 로컬 라이프스타일 브랜드입니다.', '올레올레는 제주의 정취와 환대 문화를 상품에 담아낸 제주 로컬 라이프스타일 브랜드입니다. 제주의 맑은 자연을 모티브로 한 디자인 굿즈와 특산물을 통해 여행의 설렘과 여운을 일상 속으로 전달합니다.', 'https://tong.visitkorea.or.kr/cms/resource/84/4045984_image2_1.png'),
(3011, '올레캠프 본점 알파캠프', '제주특별자치도 서귀포시 김정문화로41번길 10-1(법환동, 탐라해오름 2층)', 33.2524008, 126.5095821, 'TRAIL', 3, '알파캠프는 한달동안 제주도 올레길을 완주할 수 있도록 지원해주는 국내 유일의 트레킹 여행 지원캠프이다.', '알파캠프는 한달동안 제주도 올레길을 완주할 수 있도록 지원해주는 국내 유일의 트레킹 여행 지원캠프이다.INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(3208, '제주냥이', '제주특별자치도 제주시 구좌읍 해맞이해안로 1178-1', 33.5335231, 126.8397033, 'COMMERCIAL', 1, '캐릭터의 실제 모델인 치즈냥이가 반겨주는 제주 소품샵', '캐릭터의 실제 모델인 치즈냥이가 반겨주는 제주 소품샵', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/15/a9a760df-72f0-4fb5-8af7-5f4865b3f577.webp'),
(3209, '제주농업생태원', '제주특별자치도 서귀포시 남원읍 중산간동로 7413', 33.2880950, 126.6070300, 'THEME', 3, '서귀포 중산간에 자리한 서귀포농업기술센터 제주농업생태원은 감귤에 관한 모든 궁금증을 풀어주는 곳이다.', '서귀포 중산간에 자리한 서귀포농업기술센터 제주농업생태원은 감귤에 관한 모든 궁금증을 풀어주는 곳이다. 넓은 부지에 제주감귤홍보관과 감귤품종전시실, 감귤숲길, 감귤따기 체험장 등을 갖추고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202002/25/d0a3946a-0f2c-4bd5-beb1-e7dfea773941.webp'),
(3210, '제주다', '제주특별자치도 제주시 애월읍 납읍남로 65', 33.4310983, 126.3293946, 'EXPERIENCE', 2, '제주조릿대로 만드는 향긋한 차 체험을 할 수 있는 곳', '제주조릿대로 만드는 향긋한 차 체험을 할 수 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/201811/29/0536ea75-aa3e-4654-8e52-ededbaca7293.webp'),
(3211, '제주대 벚꽃길', '제주특별자치도 제주시 제주대학로 102', 33.4579467, 126.5624124, 'TRAIL', 4, '제주대 벚꽃길은 제주도에서 가장 유명한 벚꽃 명소 중 하나이다.', '제주대 벚꽃길은 제주도에서 가장 유명한 벚꽃 명소 중 하나이다. 제주시청을 지나 1131번 도로를 타고 내려가다 보면 왼편으로 제주대학교 진입로가 나타난다. 제주대학교 입구까지 도로변에 벚나무들이 즐비하게 늘어서 있으며, 만개한 벚꽃을 보기 위해 많은 이들의 발걸음이 이어지고 있다. 꽃 터널을 지나가는 듯한 환상적인 기분을 느낄 수 있는 드라이브 코스로, 만개한 꽃송이가 떨어지는 광경이 눈이 내린 설경을 보는 것 전해질 정도로 아름다운 벚꽃길을 만끽할 수 있다.', 'https://tong.visitkorea.or.kr/cms/resource/93/3477793_image2_1.jpg'),
(3212, '제주도 관광특구', '제주특별자치도', 33.3911586, 126.4961419, 'NATURE', 4, '한반도의 남서해상에 위치하는 제주도는 특별자치도로 지정된 국내 최대의 관광 지역이다.', '한반도의 남서해상에 위치하는 제주도는 특별자치도로 지정된 국내 최대의 관광 지역이다. 전 지역이 관광특구로 지정될 만큼 발길 닿는 곳마다 아름다운 자연 경관이 펼쳐진다. 내외국인을 합쳐 한 해 약 1,500만명 이상의 관광객이 다녀갈 정도로 매력적인 이 섬의 크기는 남북으로 31㎞, 동서로 73㎞에 이른다. 유네스코 3관왕(세계자연유산, 세계지질공원, 생물권보전지역) 지역이며, 세계7대자연경관 지역으로 지정된 제주도는 온대 지방의 특징을 가진 한반도의 육지와는 다른 기후대에 자리했다. 덕분에 아열대에서 아한대에 이르는 제주만의 식생을 보유했다.
INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(3408, '차귀도 바다낚시', '제주특별자치도 제주시 한경면 고락로 200-52', 33.3011473, 126.2053164, 'LEISURE', 2, '차귀도는 제주의 여러 섬 중에서 빼어난 절경을 자랑하는 섬이다.', '차귀도는 제주의 여러 섬 중에서 빼어난 절경을 자랑하는 섬이다. 제주시 한경면 고산리 자구내포구에서 뱃길로 10분 거리에 있다. 차귀도 주변 바다는 수심이 깊고 참돔, 돌돔, 흑돔, 벤자리, 자바리 등의 다양한 어종이 잡힌다. 특히 1~3월 사이 낚시꾼이 많이 몰린다. 차귀도 주위를 한 바퀴 돌아볼 수 있는 쾌속정이 수시로 운항하며, 낚시할 도구가 없을 경우에도 낚시도구가 갖추어진 소형어선을 빌려 배낚시가 가능하다. 어족이 풍부하여 낚시 경험이 없는 초보자도 고기가 잘 잡힌다. 배에는 약 15명 내외 인원이 탑승이 가능하기 때문에 함께 온 친구나 연인, 가족들과 함께 낚시를 즐길 수 있다. 워낙 입질이 잦기 때문에 낚싯줄을 던지자마자 물고기가 잡히는 경우도 있다.', 'https://tong.visitkorea.or.kr/cms/resource/31/3477931_image2_1.jpg'),
(3409, '차귀도달래배낚시체험', '제주특별자치도 제주시 한경면 노을해안로 1160', 33.3089090, 126.1649209, 'EXPERIENCE', 2, '차귀도 앞바다에서 즐기는 낚시의 손맛', '차귀도 앞바다에서 즐기는 낚시의 손맛', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/20/ba71e43d-6735-46a0-8040-2b43b186a936.webp'),
(3410, '차귀도요트', '제주특별자치도 제주시 한경면 한경해안로 156', 33.3239750, 126.1660310, 'LEISURE', 2, '제주 서부 해역에 자리 잡은 요트 수상레저사업장으로 세일링요트와 파워낚시보트를 보유하고 있으며 별도의 구조선과 안전요원이 항시 대기 중으로 안…', '제주 서부 해역에 자리 잡은 요트 수상레저사업장으로 세일링요트와 파워낚시보트를 보유하고 있으며 별도의 구조선과 안전요원이 항시 대기 중으로 안전하고 여유롭게 이용 가능하다. 운항 코스는 이국적인 자연 경관을 배경으로 당산봉 해안절벽과 차귀도를 최대한 근접하여 운항할 뿐만 아니라 어족자원이 풍부한 포인트에서 손맛을 바로 느낄 수 있는 체험낚시와 열대어들과 함께 노닐 수 있는 스노클링도 함께 즐길 수 있으며, 남방 큰 돌고래와 함께 운항도 할 수 있다.', 'https://tong.visitkorea.or.kr/cms/resource/91/4073091_image2_1.jpg'),
(3411, '참굴비조형물', '제주특별자치도 제주시 추자면 묵리 산 131-1', 33.9525760, 126.3043200, 'NATURE', 4, '추자도의 상징인 참굴비 조형물', '추자도의 상징인 참굴비 조형물', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/ba79277b-e2cd-4dde-8201-5e44abc7ebed.webp'),
(3412, '창고천생태공원', '제주특별자치도 서귀포시 안덕면 일주서로 1524', 33.2584150, 126.3530600, 'NATURE', 2, '안덕지역을 통과하는 생태 공원', '안덕지역을 통과하는 생태 공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/e32cf2be-c7af-4f9d-8f63-b40873fd3d0a.webp'),
(3413, '책가방', '제주특별자치도 제주시 동문로14길 11', 33.5125427, 126.5334052, 'COMMERCIAL', 4, '''책이 가득한 방''이라는 뜻의 작고 아담한 동네서점', '''책이 가득한 방''이라는 뜻의 작고 아담한 동네서점', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/15/2be958d5-05c6-4a52-a468-5f03f47371b7.webp'),
(3414, '책계일주', '제주특별자치도 서귀포시 표선면 토산중앙로49번길 41 1층', 33.3078165, 126.7762537, 'NATURE', 1, '세계일주를 콘셉트로 책과 술을 같이 즐길 수 있는 북카페', '세계일주를 콘셉트로 책과 술을 같이 즐길 수 있는 북카페', 'https://api.cdn.visitjeju.net/photomng/imgpath/202506/10/6a5f4566-ae50-44be-ae8c-7be3c2a8d88e.webp'),
(3415, '책방 소리소문', '제주특별자치도 제주시 한경면 저지동길 8-31', 33.3325535, 126.2595339, 'COMMERCIAL', 2, '죽기 전에 꼭 가봐야 할 세계 서점 150곳 중 하나', '죽기 전에 꼭 가봐야 할 세계 서점 150곳 중 하나', 'https://api.cdn.visitjeju.net/photomng/imgpath/202512/03/00f99a54-f9fc-465c-8c85-c75b41c578f9.webp'),
(3416, '책약방', '제주특별자치도 제주시 구좌읍 종달로5길 11', 33.4929547, 126.8976924, 'CULTURE', 1, '조용한 초등학교 앞 정겨운 골목길을 천천히 걷다 보면 동화 속에서 튀어나온 듯 아기자기한 외관의 작은 책방이 여행자의 발길을 붙잡는다.', '조용한 초등학교 앞 정겨운 골목길을 천천히 걷다 보면 동화 속에서 튀어나온 듯 아기자기한 외관의 작은 책방이 여행자의 발길을 붙잡는다. 이곳은 쓴 약 대신 달콤한 그림책으로 일상에 지친 사람들의 마음을 따스하게 다독이고자 문을 연 이색적인 무인 서점이다. 주인 없이 이십사 시간 내내 언제나 활짝 열려 있는 아담한 실내로 들어서면 누군가의 정성스러운 손길로 채워진 포근한 서가가 방문객을 반갑게 맞이한다. 책장에는 아이들의 순수한 상상력을 자극하는 도서부터 어른의 내면을 다정하게 위로해 주는 그림책과 산문집까지 다채로운 읽을거리가 정갈하게 꽂혀 있다. 그 밖에도 먼저 다녀간 여행자들이 정성껏 남겨 놓은 방명록의 흔적을 찬찬히 읽어보며 나만의 온전한 휴식 시간을 누릴 수 있는 것이 이곳만의 특별한 매력이다.', 'https://tong.visitkorea.or.kr/cms/resource/30/4106830_image2_1.jpg'),
(3417, '책은 선물', '제주특별자치도 제주시 한경면 신창5길 5', 33.3491801, 126.1820167, 'COMMERCIAL', 2, '일일 서점지기 체험이 가능한 작은 서점', '일일 서점지기 체험이 가능한 작은 서점', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/15/05dc24f9-60b7-415b-bf27-57361e59147d.webp'),
(3418, '천아오름', '제주특별자치도 제주시 애월읍 광령리', 33.3969294, 126.4499096, 'NATURE', 2, '어승생악 서쪽 지점 신엄공동목장 안에 위치한 오름으로, 남쪽 봉우리를 중심으로 북서쪽으로 패어있는 소규모 말굽형 화구를 이루고 있다.', '어승생악 서쪽 지점 신엄공동목장 안에 위치한 오름으로, 남쪽 봉우리를 중심으로 북서쪽으로 패어있는 소규모 말굽형 화구를 이루고 있다. 천아오름이라는 이름은 옛 지도에 이곳이 참나무봉우리로 표기된 것에서 따왔다. 해송이 주종을 이루며 잡목이 우거지고 꽝꽝나무가 많다. 천아오름 동녘 자락에 속칭 무수내(무수천 상류)가 있고, 이 냇가에는 어승생저수지의 보조수원인 천아수원이 개발되어 있다. 제주시와 애월읍의 경계를 이루며 계곡 양안에서 우거진 온대림은 참꽃나무와 낙엽활엽수의 단풍 등이 있어 경치가 수려하다. 오름은 경사가 완만하여 굳이 오르지 않더라도 평탄하고 주변의 어승생악, 붉은오름 등을 관찰할 수 있다. 천아오름은 사유지이며 탐방로가 정비가 되어있지 않아 천아계곡까지만 탐방하는 것을 추천한다.', 'https://tong.visitkorea.or.kr/cms/resource/93/3526993_image2_1.jpg'),
(3419, '천아오름(틍낭오름,天娥岳)', '제주특별자치도 제주시 애월읍 산록서로 678-207', 33.3962598, 126.4888362, 'NATURE', 4, '경승이 빼어난 천아오름', '경승이 빼어난 천아오름', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/1717ec5c-418e-4258-9cea-0eb98ca0fe22.webp'),
(3420, '천주교 대정성지', '제주특별자치도 서귀포시 대정읍 추사로247번길 102', 33.2535840, 126.2607820, 'HISTORY', 2, '대정성지는 다산 정약용의 조카이자 제주 최초의 천주교인 정난주 마리아의 묘가 안치된 곳이다.', '대정성지는 다산 정약용의 조카이자 제주 최초의 천주교인 정난주 마리아의 묘가 안치된 곳이다. 그녀의 남편인 황사영은 신유박해의 실상을 저술한 백서를 청나라에 보내려다가 발각되어 처형당했고, 그녀 역시 제주로 유배되었다. 제주 관노로 전락했음에도 신앙심을 잃지 않고 그녀의 풍부한 교양과 학식으로 주민들을 교화해 이웃들의 칭송을 받았다고 한다. 그녀가 세상을 떠나자 주민들은 그녀를 추모하는 공간을 마련했고, 훗날 천주교는 이곳을 대정성지로 꾸며 성지순례 장소 중 하나가 되었다.', 'https://tong.visitkorea.or.kr/cms/resource/03/3391703_image2_1.jpg'),
(3421, '천주교 순례길 - 김기량길', '제주특별자치도 제주시 조천읍 조천2길 19', 33.5329060, 126.6316300, 'CULTURE', 1, '조천 성당부터 복자 김기량 펠릭스베드로 순교헌양비까지 순례자길', '조천 성당부터 복자 김기량 펠릭스베드로 순교헌양비까지 순례자길', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/3674d610-0710-4b0d-b48d-7110cb1b54d2.webp'),
